// ── Helpers ──
function arrowTip(x, y, angle, size, color) {
  var s = size || 9;
  var a1 = angle - 0.38, a2 = angle + 0.38;
  var pts = [[x, y],[x - s*Math.cos(a1), y - s*Math.sin(a1)],[x - s*Math.cos(a2), y - s*Math.sin(a2)]];
  return draw.polygon(pts.map(function(p){return p[0]+','+p[1];}).join(' ')).fill(color || COL);
}
function drawArrow(x1,y1,x2,y2,color,w) {
  var c = color||COL, ww = w||1.5;
  var ln = draw.line(x1,y1,x2,y2).stroke({color:c,width:ww});
  var ang = Math.atan2(y2-y1,x2-x1);
  var hd = arrowTip(x2,y2,ang,9,c);
  return {line:ln, head:hd, setColor:function(nc){ln.stroke({color:nc});hd.fill(nc);}};
