els.acceptLabel = plainText(EQ_X+EQ_W+34, EQ_Y+EQ_H/2+5, 'accept', FS, COL, 'start');

// Reject arrow and label (hidden initially)
els.rejectArrow = drawArrow(EQ_X+EQ_W, EQ_Y+EQ_H/2+8, EQ_X+EQ_W+28, EQ_Y+EQ_H+18, RED, 1.5);
els.rejectLabel = plainText(EQ_X+EQ_W+34, EQ_Y+EQ_H+22, 'reject', FS, RED, 'start');
els.rejectArrow.line.attr({opacity:0}); els.rejectArrow.head.attr({opacity:0});
els.rejectLabel.attr({opacity:0});

// "communication channel" label
els.chLabel = plainText(450, CH_Y + 32, 'communication channel', FS, COL, 'middle');

// ── Hover zones ──
// Sigma branch hover (vertical + horizontal into P_A)
var sigmaHover = draw.rect(30, PA_Y+PA_H/2-10, BSPLIT_X-PA_X+40, CH_Y-PA_Y-PA_H/2+20)
  .attr({x:BSPLIT_X-15, y:PA_Y+PA_H/2-10, width:PA_X-BSPLIT_X+20, height:CH_Y-PA_Y-PA_H/2+20})
  .fill('transparent').css('cursor','pointer');
sigmaHover.on('mousemove',function(e){showTooltip('The signature σ is fed into P_A (the public-key transform). What reaches the =? box is P_A(σ), not σ itself.',e);});
sigmaHover.on('mouseleave',function(){hideTooltip();});

// Message branch hover (M' going up to =? box)
var mHover = draw.rect(20, EQ_Y+EQ_H, 40, CH_Y-EQ_Y-EQ_H+10)
  .attr({x:EQ_CX-10, y:EQ_Y+EQ_H, width:20, height:CH_Y-EQ_Y-EQ_H+10})
  .fill('transparent').css('cursor','pointer');
mHover.on('mousemove',function(e){showTooltip('The message M\u2032 bypasses P_A and feeds the =? box directly. The comparison is between the raw received message and P_A(σ).',e);});
mHover.on('mouseleave',function(){hideTooltip();});

// S_A box hover
els.saBox.css('cursor','pointer');
els.saBox.on('mousemove',function(e){showTooltip('S_A is Alice\u2019s secret signing transform. Only Alice can compute σ = S_A(M\u2032).',e);});
els.saBox.on('mouseleave',function(){hideTooltip();});
els.saBox.on('click',function(){showPopup('Signing Transform S_A','Alice applies her secret key S_A to the message M\u2032 to produce the signature σ. This is a one-way operation: anyone can verify with P_A, but only Alice can sign.');});

// P_A box hover
els.paBox.css('cursor','pointer');
els.paBox.on('mousemove',function(e){showTooltip('P_A is Alice\u2019s public verification key. It transforms σ back toward M\u2032 for comparison.',e);});
els.paBox.on('mouseleave',function(){hideTooltip();});
els.paBox.on('click',function(){showPopup('Public Key P_A','Bob applies Alice\u2019s public key P_A to the received signature σ. If the signature is valid, P_A(σ) = M\u2032. Anyone with P_A can verify, but only Alice can produce a valid σ.');});

// =? box hover
els.eqBox.css('cursor','pointer');
els.eqBox.on('mousemove',function(e){showTooltip('The comparison box checks whether P_A(σ) equals the received M\u2032. Equal → accept; different → reject.',e);});
els.eqBox.on('mouseleave',function(){hideTooltip();});
els.eqBox.on('click',function(){showPopup('The =? Comparison','This is the security core: accept if and only if P_A(σ) = M\u2032. Any tampering with M\u2032 or σ on the channel breaks this equality, forcing a reject.');});

// ── State management ──
var phase = 'idle';
var tampered = false;
var PHASES = ['idle','sign','transmit','verify','compare'];
var phaseIdx = 0;

function setPhaseColor(el, color) {
  if (el.setColor) el.setColor(color);
}
function setBoxColor(box, strokeColor) {
  box.stroke({color: strokeColor, width: strokeColor===COL?1.2:2.2});
}
function setTextColor(el, color) {
  el.fill(color);
}

function applyState() {
  var c = COL;
  // Reset all to default
  setPhaseColor(els.channel, COL);
  setPhaseColor(els.saInV, COL); setPhaseColor(els.saInH, COL);
  setPhaseColor(els.saOutH, COL); setPhaseColor(els.saOutV, COL);
  setBoxColor(els.saBox, COL);
  setPhaseColor(els.paInV, COL); setPhaseColor(els.paInH, COL);
  setPhaseColor(els.paOutH, COL); setPhaseColor(els.paOutV, COL);
  setBoxColor(els.paBox, COL);
  setPhaseColor(els.mToEq, COL);
  setBoxColor(els.eqBox, COL);
  setPhaseColor(els.acceptArrow, COL);
  setTextColor(els.acceptLabel, COL);
  setTextColor(els.mLabel, COL);
  setTextColor(els.mLabel2, COL);
  setTextColor(els.sigmaLabel, COL);
  setTextColor(els.pairLabel, COL);

  // Tampered state
  if (tampered) {
    setTextColor(els.mLabel, RED);
    setTextColor(els.mLabel2, RED);
    setTextColor(els.sigmaLabel, RED);
    setTextColor(els.pairLabel, RED);
    els.acceptArrow.line.attr({opacity:0}); els.acceptArrow.head.attr({opacity:0});
    els.acceptLabel.attr({opacity:0});
    els.rejectArrow.line.attr({opacity:1}); els.rejectArrow.head.attr({opacity:1});
    els.rejectLabel.attr({opacity:1});
    setBoxColor(els.eqBox, RED);
  } else {
    els.acceptArrow.line.attr({opacity:1}); els.acceptArrow.head.attr({opacity:1});
    els.acceptLabel.attr({opacity:1});
    els.rejectArrow.line.attr({opacity:0}); els.rejectArrow.head.attr({opacity:0});
    els.rejectLabel.attr({opacity:0});
  }

  // Phase highlighting
  if (phase === 'sign') {
    setPhaseColor(els.saInV, BLUE); setPhaseColor(els.saInH, BLUE);
    setPhaseColor(els.saOutH, BLUE); setPhaseColor(els.saOutV, BLUE);
    setBoxColor(els.saBox, BLUE);
  } else if (phase === 'transmit') {
    // Highlight channel segment between DROP_X and BSPLIT_X
    els.channel.setColor(BLUE);
    setTextColor(els.pairLabel, BLUE);
  } else if (phase === 'verify') {
    setPhaseColor(els.paInV, BLUE); setPhaseColor(els.paInH, BLUE);
    setBoxColor(els.paBox, BLUE);
    setTextColor(els.sigmaLabel, BLUE);
  } else if (phase === 'compare') {
    setPhaseColor(els.paOutH, BLUE); setPhaseColor(els.paOutV, BLUE);
    setPhaseColor(els.mToEq, BLUE);
    setBoxColor(els.eqBox, tampered ? RED : BLUE);
    if (!tampered) {
      setPhaseColor(els.acceptArrow, GREEN);
      setTextColor(els.acceptLabel, GREEN);
    }
  }
}

// ── UI handlers ──
window.cyclePhase = function() {
  phaseIdx = (phaseIdx + 1) % PHASES.length;
  phase = PHASES[phaseIdx];
  var btn = document.getElementById('phaseBtn');
  btn.textContent = phase === 'idle' ? 'Step through the protocol' : 'Phase: ' + phase;
  btn.classList.toggle('active', phase !== 'idle');
  applyState();
};

window.toggle_tampered = function(on) {
  tampered = on;
  applyState();
};

// ── Demo steps ──
var steps = [
  {title:'Sign', narration:'Alice applies her secret signing transform S_A to the message M\u2032, producing the signature σ = S_A(M\u2032). Only the S_A box and its input/output edges are lit.', state:{phase:'sign',tampered:false}},
  {title:'Transmit', narration:'The message and its signature travel together as the pair (M\u2032, σ) along the communication channel toward Bob.', state:{phase:'transmit',tampered:false}},
  {title:'Verify', narration:'Bob splits the pair: σ is fed up into the public-key box P_A while M\u2032 continues along the bottom. Hover each branch to see that σ is transformed but M\u2032 is not.', state:{phase:'verify',tampered:false}},
  {title:'Compare — accept', narration:'The =? box receives P_A(σ) from above and M\u2032 from below. With an untampered channel they are equal, so the box outputs accept.', state:{phase:'compare',tampered:false}},
  {title:'Compare — reject', narration:'Now flip the channel to Tampered: M\u2032 (or σ) is altered in transit, so P_A(σ) no longer equals the received message and the =? box outputs reject instead of accept.', state:{phase:'compare',tampered:true}}
];
var curStep = 0;

function goToStep(n) {
  curStep = Math.max(0, Math.min(steps.length, n));
  var lbl = document.getElementById('stepLabel');
  var nar = document.getElementById('demoNarration');
  if (curStep === 0) {
    lbl.textContent = '0 / ' + steps.length;
    nar.textContent = 'Click \u25B6 to begin the guided walkthrough of the digital signature protocol.';
    phase = 'idle'; tampered = false;
    document.getElementById('tamperedInput').checked = false;
    document.getElementById('phaseBtn').textContent = 'Step through the protocol';
    document.getElementById('phaseBtn').classList.remove('active');
  } else {
    var s = steps[curStep - 1];
    lbl.textContent = curStep + ' / ' + steps.length;
    nar.textContent = s.title + ': ' + s.narration;
    phase = s.state.phase;
    tampered = s.state.tampered;
    document.getElementById('tamperedInput').checked = tampered;
    phaseIdx = PHASES.indexOf(phase);
    document.getElementById('phaseBtn').textContent = 'Phase: ' + phase;
    document.getElementById('phaseBtn').classList.add('active');
  }
  applyState();
}

window.nextStep = function(){ goToStep(curStep + 1); };
window.prevStep = function(){ goToStep(curStep - 1); };

// Initial state
applyState();
window.__markRendered();
})();
// @FIGURE_CODE_END

